/** A taxonomy term (category or tag) carried over from WordPress. */
export interface BlogTerm {
  readonly name: string;
  readonly slug: string;
}

/**
 * Full data for one migrated blog post. One module per post lives in
 * src/data/blog/<slug>.ts and is code-split so visiting a post only loads
 * that post's body. Generated by scripts/build-blog.mjs from the WordPress export.
 */
export interface BlogPostData {
  /** Matches the route and the original WordPress permalink: /<slug>/ */
  readonly slug: string;
  readonly title: string;
  /** Plain-text summary (no markup), used for meta description fallback and cards. */
  readonly excerpt: string;
  /** Cleaned article HTML body (typography normalised, images rewritten to local paths). */
  readonly html: string;
  /** ISO date 'YYYY-MM-DD' of publication (for schema + display). */
  readonly date: string;
  /** ISO date 'YYYY-MM-DD' last modified. */
  readonly modified: string;
  readonly author: string;
  readonly categories: readonly BlogTerm[];
  readonly tags: readonly BlogTerm[];
  /** Local featured-image path (/blog-media/...) or undefined when the post had none. */
  readonly featuredImage?: string;
  readonly featuredImageAlt?: string;
  /** Minutes, from word count ÷ 225. */
  readonly readingTime: number;
  readonly seo: {
    readonly title: string;
    readonly description: string;
  };
}

/**
 * Lightweight card metadata for the /blogs listing. Kept free of `html` so the
 * listing bundle never pulls in 109 article bodies. Generated into src/data/blog/index.ts.
 */
export interface BlogListItem {
  readonly slug: string;
  readonly title: string;
  readonly excerpt: string;
  /** ISO date 'YYYY-MM-DD'; used for sorting and display. */
  readonly date: string;
  readonly author: string;
  readonly category?: string;
  /** Local featured-image path, or undefined (listing falls back to a bundled image). */
  readonly featuredImage?: string;
  readonly featuredImageAlt?: string;
  readonly readingTime: number;
}
